async function saveSpecReport(type,button){button.disabled=true;const old=button.textContent;button.textContent='정리본 생성 중…';try{const rows=reportRows(),meta=reportMeta(),filename=exportDatePrefix()+safeDrawingName(site.name,'현장-1')+'-창호상세내역.'+type;if(type==='jpg')await downloadDrawingCanvas(await reportCanvas(rows,meta),filename);else{const blob=await reportXlsx(rows,meta),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}}catch(error){console.error(error);toast('정리본 저장에 실패했습니다. 다시 시도해 주세요.');}finally{button.disabled=false;button.textContent=old;}}

function revealNextGuide(id,focus=false){if(![2,3,6].includes(step))return;const card=[...document.querySelectorAll('[data-card]')].find(e=>e.dataset.card===id),el=card?.querySelector('.is-next');if(!el)return;if(focus){const input=el.querySelector('input');if(input){input.focus({preventScroll:true});input.select();}}requestAnimationFrame(()=>{const rect=el.getBoundingClientRect(),top=document.querySelector('.app-masthead')?.getBoundingClientRect().bottom||140;if(rect.bottom>innerHeight-20)window.scrollBy({top:Math.min(rect.bottom-innerHeight+24,rect.top-top-16),behavior:'smooth'});else if(rect.top<top)el.scrollIntoView({block:'center',behavior:'smooth'});});}
let reportImageCache;
