async function imageFallback(blob){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=exportDatePrefix()+safeDrawingName(site.name,'현장-1')+'-창호상세내역.png';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('이 브라우저에서는 이미지 전달을 지원하지 않습니다. 저장된 그림을 카카오톡에 첨부해 주세요.');}
